#!/usr/bin/env bash
set -euo pipefail

# Print the Jira key to reference in a translation commit pushed by technique-ci.
#
# The key is the one already referenced by the pull request (branch name, then description),
# else the one of a new MON ticket: outside a pull request, every translation commit gets its own ticket.
#
# Never fails: prints nothing (and a warning on stderr) when no key can be resolved.
#
# Usage: get-jira-key.sh <project_name>
#
# Expected environment variables:
#   JIRA_BASE_URL, JIRA_USER_EMAIL, JIRA_API_TOKEN - Jira credentials (may be empty, e.g. fork pull request)
#   BRANCH_NAME                                    - branch receiving the commit
#   RUN_URL                                        - URL of the workflow run
#   HEAD_REF, PR_BODY, PR_URL                      - pull request context (empty on push events)

PROJECT_NAME="${1:?project name is required}"
BRANCH_NAME="${BRANCH_NAME:-}"
RUN_URL="${RUN_URL:-}"
PR_URL="${PR_URL:-}"

JIRA_PROJECT_KEY="MON"
JIRA_ISSUE_TYPE_ID="10209" # Technical
JIRA_SQUAD_FIELD="customfield_10902"
JIRA_SQUAD_ID="10524" # DEVSECOPS

warn() {
  echo "::warning::$*" >&2
}

# Same pattern as the check-jira-reference job of check-status.yml
find_jira_key() {
  TEXT="$1" php -r '
    $ignoredPrefixes = ["CVE", "CWE", "GHSA", "ISO", "RFC", "SHA", "TLS", "UTF"];
    preg_match_all(
      "/(?<![A-Za-z0-9_])([A-Z]{2}[A-Z0-9_]*)-[1-9][0-9]*(?![A-Za-z0-9])/",
      (string) getenv("TEXT"),
      $matches,
      PREG_SET_ORDER
    );
    foreach ($matches as $match) {
      if (! in_array($match[1], $ignoredPrefixes, true)) {
        echo $match[0];
        break;
      }
    }
  '
}

jira_curl() {
  # credentials are given through a config file to keep them out of the process list
  curl --silent --show-error --fail --max-time 30 \
    --config <(printf 'user = "%s:%s"\n' "$JIRA_USER_EMAIL" "$JIRA_API_TOKEN") \
    --header "Accept: application/json" \
    "$@"
}

main() {
  local text key="" summary response payload

  for text in "${HEAD_REF:-}" "${PR_BODY:-}"; do
    key="$(find_jira_key "$text")"
    if [[ -n "$key" ]]; then
      echo "Reusing Jira ticket ${key} referenced by the pull request." >&2
      echo "$key"
      return 0
    fi
  done

  if [[ -z "${JIRA_BASE_URL:-}" || -z "${JIRA_USER_EMAIL:-}" || -z "${JIRA_API_TOKEN:-}" ]]; then
    warn "Jira credentials are not available. No Jira ticket will be referenced by the translation commit."
    return 0
  fi

  if [[ -z "$BRANCH_NAME" ]]; then
    warn "BRANCH_NAME is not set. No Jira ticket will be referenced by the translation commit."
    return 0
  fi

  summary="Update translations of ${PROJECT_NAME} on ${BRANCH_NAME}"

  payload="$(
    SUMMARY="$summary" BRANCH_NAME="$BRANCH_NAME" RUN_URL="$RUN_URL" PR_URL="$PR_URL" \
    PROJECT_KEY="$JIRA_PROJECT_KEY" ISSUE_TYPE_ID="$JIRA_ISSUE_TYPE_ID" \
    SQUAD_FIELD="$JIRA_SQUAD_FIELD" SQUAD_ID="$JIRA_SQUAD_ID" php -r '
      $link = static fn (string $text, string $url): array => [
        "type" => "text",
        "text" => $text,
        "marks" => [["type" => "link", "attrs" => ["href" => $url]]],
      ];
      $content = [[
        "type" => "text",
        "text" => "Translation files have been regenerated by the CI on branch " . getenv("BRANCH_NAME") . ".",
      ]];
      if (getenv("RUN_URL")) {
        $content[] = ["type" => "text", "text" => " "];
        $content[] = $link("Workflow run", getenv("RUN_URL"));
      }
      if (getenv("PR_URL")) {
        $content[] = ["type" => "text", "text" => " - "];
        $content[] = $link("Pull request", getenv("PR_URL"));
      }
      echo json_encode([
        "fields" => [
          "summary" => getenv("SUMMARY"),
          "project" => ["key" => getenv("PROJECT_KEY")],
          "issuetype" => ["id" => getenv("ISSUE_TYPE_ID")],
          "labels" => ["Pipeline", "Translation"],
          getenv("SQUAD_FIELD") => ["id" => getenv("SQUAD_ID")],
          "description" => [
            "type" => "doc",
            "version" => 1,
            "content" => [["type" => "paragraph", "content" => $content]],
          ],
        ],
      ]);
    '
  )"

  if response="$(jira_curl --request POST --url "${JIRA_BASE_URL}/rest/api/3/issue" \
    --header "Content-Type: application/json" --data "$payload")"; then
    key="$(RESPONSE="$response" php -r 'echo json_decode((string) getenv("RESPONSE"), true)["key"] ?? "";')"
  fi

  if [[ -z "$key" ]]; then
    warn "Failed to create a Jira ticket. No Jira ticket will be referenced by the translation commit."
    return 0
  fi

  echo "Created Jira ticket ${key}." >&2
  echo "$key"
}

main
